import{_ as t,o as d,c as o,a6 as r}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse(`{"title":"MCP tools","description":"Every tool the dashboard's MCP server serves, by module, with the capability that removes it when declined, generated from the tool catalog.","frontmatter":{"title":"MCP tools","description":"Every tool the dashboard's MCP server serves, by module, with the capability that removes it when declined, generated from the tool catalog.","lang":"en-US","editLink":false,"head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/mcp-tools.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/mcp-tools.html"}],["meta",{"property":"og:title","content":"MCP tools | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every tool the dashboard's MCP server serves, by module, with the capability that removes it when declined, generated from the tool catalog."}]]},"headers":[],"relativePath":"reference/mcp-tools.md","filePath":"reference/mcp-tools.md","lastUpdated":null}`),c={name:"reference/mcp-tools.md"};function s(a,e,i,n,u,l){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="mcp-tools" tabindex="-1">MCP tools <a class="header-anchor" href="#mcp-tools" aria-label="Permalink to &quot;MCP tools&quot;">​</a></h1><p>The <a href="/features/mcp.html">MCP server</a> serves 86 tools. Each belongs to one <strong>module</strong>, the groups the Setup page asks about, and <code>?modules=</code> on the MCP URL narrows the list to some of them. A tool with a <strong>capability</strong> leaves <code>tools/list</code> and <code>tools/call</code> when an administrator declines that capability for the instance; a tool without one is always served.</p><p>Each entry here is the summary line of the description the server sends to the agent, and the names of its parameters. The <strong>MCP server</strong> page of the dashboard (<code>/mcp</code>) lists the same catalog with each tool&#39;s whole description and each parameter&#39;s, and leaves out the tools of declined capabilities.</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><p>51 of the 86 tools. Setup offers this module as <strong>See why tests fail</strong>: run history, traces, failure clusters and flaky scoring.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Parameters</th><th>Capability</th></tr></thead><tbody><tr><td><code id="list_projects">list_projects</code></td><td>List the projects you can read, with their run and test-case counts and their latest run.</td><td>none</td><td>none</td></tr><tr><td><code id="get_project">get_project</code></td><td>Get one project with its recent runs and their pass and fail counts, newest first.</td><td><code>projectId</code> (required), <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="list_runs">list_runs</code></td><td>List a project’s test runs, newest first, optionally filtered by status or branch.</td><td><code>projectId</code> (required), <code>status</code>, <code>branch</code>, <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="get_run">get_run</code></td><td>Get a test run’s summary and its test cases (by default only the failed ones), each with its status, truncated error and failure cluster.</td><td><code>runId</code> (required), <code>statusFilter</code>, <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="list_failed_cases">list_failed_cases</code></td><td>List a project’s failed and timed-out executions across recent runs, each with a one-line headline ahead of its truncated error.</td><td><code>projectId</code> (required), <code>pageSize</code>, <code>cursor</code>, <code>runId</code></td><td>none</td></tr><tr><td><code id="list_flaky_tests">list_flaky_tests</code></td><td>List a project’s flaky tests, highest flakiness score first.</td><td><code>projectId</code> (required), <code>runs</code>, <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="get_test_case">get_test_case</code></td><td>Get a test case with its pass and fail stats, its flakiness metrics and its recent executions.</td><td><code>testCaseId</code> (required), <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="list_clusters">list_clusters</code></td><td>List a project’s failure clusters, each grouping the failures that share an error fingerprint.</td><td><code>projectId</code> (required), <code>status</code>, <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="get_cluster">get_cluster</code></td><td>Get a failure cluster with its affected tests, a short diagnosis summary and the locator fixes of up to five of its failures.</td><td><code>clusterId</code> (required)</td><td>none</td></tr><tr><td><code id="get_fix_plan">get_fix_plan</code></td><td>Get everything needed to fix one failure cluster, in one answer.</td><td><code>clusterId</code> (required)</td><td>none</td></tr><tr><td><code id="get_test_case_context">get_test_case_context</code></td><td>Get the evidence Piwi’s AI reads for one failing execution: steps, console, network, backend logs and the source-control diff.</td><td><code>executionId</code> (required)</td><td>none</td></tr><tr><td><code id="get_case_screenshots">get_case_screenshots</code></td><td>List an execution’s screenshots, the page the test failed on first, and return the image data of the first three on request.</td><td><code>executionId</code> (required), <code>content</code></td><td>none</td></tr><tr><td><code id="get_cluster_context">get_cluster_context</code></td><td>Get the full evidence of a failure cluster, the same the diagnosis AI reads: the richest evidence there is for debugging a failure.</td><td><code>clusterId</code> (required), <code>baseCommit</code>, <code>selectedCommitShas</code></td><td>none</td></tr><tr><td><code id="search_test_cases">search_test_cases</code></td><td>Find a project’s test cases by title, file path or external ID, when you don’t know their <code>testCaseId</code>.</td><td><code>projectId</code> (required), <code>q</code> (required), <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="get_test_run_case">get_test_run_case</code></td><td>Get one execution in full: a one-line failure headline, the untruncated error, steps, console logs, web vitals and the ARIA snapshot.</td><td><code>executionId</code> (required), <code>include</code></td><td>none</td></tr><tr><td><code id="list_recent_activity">list_recent_activity</code></td><td>List the most recent test runs across every project you can read, newest first.</td><td><code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="get_repo_commits">get_repo_commits</code></td><td>List the recent commits of a project’s repository, with their SHA, message, author and date.</td><td><code>projectId</code> (required), <code>branch</code>, <code>limit</code></td><td><a href="/guide/source-control.html"><code>scm</code></a></td></tr><tr><td><code id="get_repo_diff">get_repo_diff</code></td><td>Get the changed files and patches of one commit in a project’s repository.</td><td><code>projectId</code> (required), <code>sha</code> (required)</td><td><a href="/guide/source-control.html"><code>scm</code></a></td></tr><tr><td><code id="get_run_insights">get_run_insights</code></td><td>Compare a run with its baseline, to answer what changed and whether a fix worked.</td><td><code>runId</code> (required), <code>baseBranch</code></td><td>none</td></tr><tr><td><code id="get_spec_health">get_spec_health</code></td><td>Get the health of each area of a project’s suite over the last N days, grouped by spec-file prefix.</td><td><code>projectId</code> (required), <code>days</code></td><td>none</td></tr><tr><td><code id="get_slow_tests">get_slow_tests</code></td><td>List a project’s slowest tests by average duration, with their maximum, minimum and trend across recent runs.</td><td><code>projectId</code> (required), <code>runs</code></td><td><a href="/guide/capture-fixtures.html"><code>fixtures</code></a></td></tr><tr><td><code id="get_performance_trend">get_performance_trend</code></td><td>Get a project’s run duration, average test duration and p90 test duration over its recent runs.</td><td><code>projectId</code> (required), <code>limit</code></td><td><a href="/guide/capture-fixtures.html"><code>fixtures</code></a></td></tr><tr><td><code id="get_test_stability_trend">get_test_stability_trend</code></td><td>Get one test’s flaky rate, pass rate and average duration over the last N days, in about 31 UTC time buckets.</td><td><code>testCaseId</code> (required), <code>days</code></td><td>none</td></tr><tr><td><code id="get_network_requests">get_network_requests</code></td><td>Get a run’s network requests grouped by method and normalized route, slowest first.</td><td><code>runId</code> (required)</td><td><a href="/guide/capture-fixtures.html"><code>fixtures</code></a></td></tr><tr><td><code id="get_failure_groups">get_failure_groups</code></td><td>Get one run’s failures grouped by failure cluster, with each group’s affected tests and worker correlation.</td><td><code>runId</code> (required)</td><td>none</td></tr><tr><td><code id="search">search</code></td><td>Search every project you can read for projects, runs, test cases and failure clusters.</td><td><code>q</code> (required)</td><td>none</td></tr><tr><td><code id="list_case_traces">list_case_traces</code></td><td>List an execution’s Playwright trace files, each with its download path.</td><td><code>executionId</code> (required)</td><td>none</td></tr><tr><td><code id="list_tags">list_tags</code></td><td>List every tag defined on this instance, with its id, text and color.</td><td>none</td><td><a href="/guide/reporter.html"><code>tags</code></a></td></tr><tr><td><code id="list_open_clusters">list_open_clusters</code></td><td>List the failure clusters of every project you can read, open ones by default, most occurrences first: a cross-project triage queue.</td><td><code>status</code>, <code>queue</code>, <code>pageSize</code>, <code>cursor</code></td><td>none</td></tr><tr><td><code id="get_instance_stats">get_instance_stats</code></td><td>Get instance-wide counts (projects, runs, test cases, executions, files) and the total storage size.</td><td>none</td><td>none</td></tr><tr><td><code id="explain_failure">explain_failure</code></td><td>Explain one failing execution in one call: its evidence, its situation and the next step.</td><td><code>executionId</code> (required)</td><td>none</td></tr><tr><td><code id="set_cluster_status">set_cluster_status</code></td><td>Set a failure cluster’s triage status to open, resolved or ignored, with an optional note.</td><td><code>clusterId</code> (required), <code>status</code> (required), <code>triageNote</code></td><td>none</td></tr><tr><td><code id="set_cluster_base_commit">set_cluster_base_commit</code></td><td>Pin the baseline commit of a failure cluster’s source-control diff, so its evidence of what changed since green is accurate.</td><td><code>clusterId</code> (required), <code>commit</code> (required)</td><td>none</td></tr><tr><td><code id="triage_cluster">triage_cluster</code></td><td>Triage one or more failure clusters at once, as the failure inbox does.</td><td><code>clusterIds</code> (required), <code>action</code> (required), <code>status</code>, <code>note</code>, <code>assignee</code>, <code>snooze</code>, <code>reason</code></td><td>none</td></tr><tr><td><code id="decide_merge_suggestion">decide_merge_suggestion</code></td><td>Approve or reject a suggestion to merge two failure clusters that look like one root cause.</td><td><code>clusterId</code>, <code>suggestionId</code>, <code>decision</code> (required)</td><td>none</td></tr><tr><td><code id="move_tests_to_new_cluster">move_tests_to_new_cluster</code></td><td>Move some tests out of a failure cluster into a new one, for a cluster that groups failures with different root causes.</td><td><code>clusterId</code> (required), <code>testCaseIds</code> (required), <code>triageNote</code></td><td>none</td></tr><tr><td><code id="rerun_cluster_in_ci">rerun_cluster_in_ci</code></td><td>Re-run exactly a failure cluster’s affected tests in CI.</td><td><code>clusterId</code> (required)</td><td><a href="/guide/source-control.html"><code>scm</code></a></td></tr><tr><td><code id="set_cluster_bisect">set_cluster_bisect</code></td><td>Record the first bad commit a <code>git bisect</code> found for a failure cluster, as the desktop app does when its bisect ends.</td><td><code>clusterId</code> (required), <code>sha</code> (required), <code>subject</code>, <code>author</code>, <code>date</code></td><td>none</td></tr><tr><td><code id="report_fix_attempt">report_fix_attempt</code></td><td>Record that you changed the code to fix a failure cluster, once the change is made, so Piwi can verify it.</td><td><code>clusterId</code> (required), <code>kind</code> (required), <code>commit</code>, <code>branch</code>, <code>patch</code>, <code>patchHash</code>, <code>edit</code>, <code>diagnosisId</code>, <code>note</code></td><td>none</td></tr><tr><td><code id="set_run_incident">set_run_incident</code></td><td>Mark a test run as an environment incident, or clear the flag, as the run page does.</td><td><code>runId</code> (required), <code>incident</code> (required), <code>reason</code></td><td>none</td></tr><tr><td><code id="describe_piwi">describe_piwi</code></td><td>Answer a question about Piwi itself from its own documentation, which ships with this server and matches the running version.</td><td><code>topic</code>, <code>page</code>, <code>query</code></td><td>none</td></tr><tr><td><code id="get_change_coverage">get_change_coverage</code></td><td>Find a pull request’s uncovered changes: the files it touched, joined to the tests that observably reach them, grouped by ticket.</td><td><code>projectId</code> (required), <code>run</code>, <code>base</code>, <code>head</code></td><td><a href="/guide/source-control.html"><code>scm</code></a></td></tr><tr><td><code id="get_coverage">get_coverage</code></td><td>Read coverage: which code ran, and which tests run it.</td><td><code>projectId</code>, <code>file</code>, <code>lines</code>, <code>branch</code>, <code>executionId</code>, <code>testCaseId</code>, <code>testFile</code>, <code>testTitle</code></td><td><a href="/features/code-reach.html"><code>coverage</code></a></td></tr><tr><td><code id="compare_coverage">compare_coverage</code></td><td>Compare the code a test ran across its executions.</td><td><code>executionId</code>, <code>testCaseId</code></td><td><a href="/features/code-reach.html"><code>coverage</code></a></td></tr><tr><td><code id="get_coverage_loss">get_coverage_loss</code></td><td>Find what quarantining, skipping or deleting tests would leave uncovered.</td><td><code>projectId</code> (required), <code>testCaseIds</code> (required)</td><td><a href="/features/code-reach.html"><code>coverage</code></a></td></tr><tr><td><code id="get_coverage_summary">get_coverage_summary</code></td><td>Get a commit’s combined coverage: every suite that ran the code, counted on one set of executable lines per file version.</td><td><code>projectId</code> (required), <code>commit</code>, <code>branch</code>, <code>folder</code>, <code>file</code>, <code>area</code></td><td><a href="/features/code-reach.html"><code>coverage</code></a></td></tr><tr><td><code id="get_release_notes">get_release_notes</code></td><td>Get what changed in each Piwi release, from the changelog shipped with this server.</td><td><code>version</code>, <code>since</code>, <code>query</code></td><td>none</td></tr><tr><td><code id="get_metric_trend">get_metric_trend</code></td><td>Get one metric over a scope: its value, its change against the comparison period, its definition and its series.</td><td><code>metric</code> (required), <code>by</code>, <code>projectIds</code>, <code>period</code>, <code>compare</code>, <code>environments</code>, <code>branches</code>, <code>allBranches</code>, <code>selection</code>, <code>tags</code>, <code>owners</code></td><td>none</td></tr><tr><td><code id="list_dashboards">list_dashboards</code></td><td>List every dashboard you can open, built-in and saved, with its id, name, description, owner, visibility and widget count.</td><td>none</td><td>none</td></tr><tr><td><code id="get_dashboard">get_dashboard</code></td><td>Get one dashboard with every widget’s data, band by band: the JSON its page renders.</td><td><code>id</code> (required), <code>by</code>, <code>projectIds</code>, <code>period</code>, <code>compare</code>, <code>environments</code>, <code>branches</code>, <code>allBranches</code>, <code>selection</code>, <code>tags</code>, <code>owners</code></td><td>none</td></tr><tr><td><code id="compare_periods">compare_periods</code></td><td>Compare a scope’s headline metrics over two periods you choose, such as this sprint against the last one.</td><td><code>a</code> (required), <code>b</code> (required), <code>metrics</code>, <code>projectIds</code>, <code>period</code>, <code>compare</code>, <code>environments</code>, <code>branches</code>, <code>allBranches</code>, <code>selection</code>, <code>tags</code>, <code>owners</code></td><td>none</td></tr></tbody></table><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>27 of the 86 tools. Setup offers this module as <strong>Triage as a team</strong>: notifications, quarantine, pull-request feedback, issue tracking and the Test Map.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Parameters</th><th>Capability</th></tr></thead><tbody><tr><td><code id="get_flake_profile">get_flake_profile</code></td><td>Get the suspects of a flaky test from its last 30 days (at most 200 attempts), and the Flake Lab experiments run on it.</td><td><code>testCaseId</code> (required)</td><td><a href="/features/flake-lab.html"><code>flake-lab</code></a></td></tr><tr><td><code id="plan_flake_experiment">plan_flake_experiment</code></td><td>Get the Flake Lab plan for a flaky test, for an agent that runs the lab itself.</td><td><code>testCaseId</code> (required)</td><td><a href="/features/flake-lab.html"><code>flake-lab</code></a></td></tr><tr><td><code id="list_resource_findings">list_resource_findings</code></td><td>List what a project’s tests leave open or let grow, across runs, most recently seen first.</td><td><code>projectId</code> (required), <code>status</code>, <code>verdict</code>, <code>limit</code></td><td><a href="/features/resource-leaks.html"><code>resources</code></a></td></tr><tr><td><code id="get_resource_profile">get_resource_profile</code></td><td>Get what one run cost and left open, from its reporters’ resource reports (one per shard).</td><td><code>runId</code> (required)</td><td><a href="/features/resource-leaks.html"><code>resources</code></a></td></tr><tr><td><code id="list_links">list_links</code></td><td>List the tickets and pull requests linked to a run, an execution, a test case or a failure cluster, with their provider and unfurled status.</td><td><code>entityType</code> (required), <code>entityId</code> (required)</td><td><a href="/features/issue-tracking.html"><code>integrations</code></a></td></tr><tr><td><code id="create_issue">create_issue</code></td><td>File a Jira issue for a failure cluster, a failing execution or a bug report, with the fix plan as its body.</td><td><code>entityType</code> (required), <code>entityId</code> (required), <code>title</code>, <code>includeDiagnosis</code>, <code>includePatch</code>, <code>locale</code>, <code>fields</code></td><td><a href="/features/issue-tracking.html"><code>integrations</code></a></td></tr><tr><td><code id="get_project_test_catalog">get_project_test_catalog</code></td><td>List a project’s whole test catalog, with each test’s pass, fail and flaky counts, average duration and last status.</td><td><code>projectId</code> (required), <code>pageSize</code>, <code>offset</code>, <code>query</code>, <code>tags</code>, <code>locks</code>, <code>owner</code>, <code>priority</code></td><td>none</td></tr><tr><td><code id="list_selections">list_selections</code></td><td>List a project’s saved test selections and the built-in ones (<code>failed</code>, <code>quarantine-free</code>).</td><td><code>projectId</code> (required)</td><td>none</td></tr><tr><td><code id="resolve_selection">resolve_selection</code></td><td>Resolve a saved or built-in selection to the tests it matches now, with a ready-to-run <code>playwright test</code> command.</td><td><code>projectId</code> (required), <code>key</code> (required), <code>format</code>, <code>budgetMs</code></td><td>none</td></tr><tr><td><code id="preview_selection">preview_selection</code></td><td>Resolve a selection definition without saving it, the dry run behind the selection builder.</td><td><code>projectId</code> (required), <code>definition</code> (required), <code>format</code></td><td>none</td></tr><tr><td><code id="suggest_selections">suggest_selections</code></td><td>Suggest tags and a smoke suite for a project from its run history, each with its evidence; nothing is saved.</td><td><code>projectId</code> (required), <code>budgetMs</code></td><td>none</td></tr><tr><td><code id="analyze_selections">analyze_selections</code></td><td>Check the health and drift of a project’s selections, read-only.</td><td><code>projectId</code> (required)</td><td>none</td></tr><tr><td><code id="get_impacted_tests">get_impacted_tests</code></td><td>Get the tests a change impacts, the ones to run and the first to check for updates, before any test runs, with a ready <code>playwright test</code> command.</td><td><code>projectId</code> (required), <code>diff</code>, <code>changedFiles</code>, <code>format</code></td><td>none</td></tr><tr><td><code id="triage_gap">triage_gap</code></td><td>Give a verdict on a scenario gap, as the gap inbox does, and return its new status.</td><td><code>projectId</code> (required), <code>gapId</code> (required), <code>verb</code> (required), <code>snooze</code>, <code>reason</code>, <code>coveringTestCaseId</code>, <code>assignedTo</code></td><td><a href="/features/scenario-gaps.html"><code>test-map</code></a></td></tr><tr><td><code id="dismiss_quarantine_proposal">dismiss_quarantine_proposal</code></td><td>Dismiss Piwi’s proposal to quarantine a test, or to release it from quarantine.</td><td><code>projectId</code> (required), <code>testCaseId</code> (required), <code>proposal</code> (required), <code>reason</code></td><td><a href="/features/flaky-tests.html"><code>quarantine</code></a></td></tr><tr><td><code id="set_test_quarantine">set_test_quarantine</code></td><td>Quarantine one test, or release it from quarantine.</td><td><code>testCaseId</code> (required), <code>quarantined</code> (required), <code>reason</code></td><td><a href="/features/flaky-tests.html"><code>quarantine</code></a></td></tr><tr><td><code id="set_bug_report_status">set_bug_report_status</code></td><td>Set a bug report’s status by hand: <code>dismissed</code> (not a bug, or not worth a test), <code>open</code> (reopen it) or <code>closed</code>.</td><td><code>id</code> (required), <code>status</code> (required)</td><td><a href="/features/bug-reports.html"><code>bug-reports</code></a></td></tr><tr><td><code id="link_issue">link_issue</code></td><td>Link an existing ticket or pull request to a failure cluster, an execution, a test case, a run or a bug report.</td><td><code>entityType</code> (required), <code>entityId</code> (required), <code>url</code> (required), <code>title</code></td><td><a href="/features/issue-tracking.html"><code>integrations</code></a></td></tr><tr><td><code id="unlink_issue">unlink_issue</code></td><td>Remove a ticket or pull request link from a failure cluster, an execution, a test case, a run or a bug report.</td><td><code>entityType</code> (required), <code>entityId</code> (required), <code>url</code> (required)</td><td><a href="/features/issue-tracking.html"><code>integrations</code></a></td></tr><tr><td><code id="create_test_function">create_test_function</code></td><td>Register a page-object method or helper in a project’s test-function catalog, so Piwi Picker and its recorder write a call to your code instead of raw locator lines.</td><td><code>projectId</code> (required), <code>name</code> (required), <code>kind</code> (required), <code>module</code> (required), <code>receiver</code>, <code>importName</code>, <code>params</code> (required), <code>returnsPage</code>, <code>urlPattern</code>, <code>steps</code> (required), <code>confidence</code>, <code>paramSources</code></td><td>none</td></tr><tr><td><code id="list_scenario_gaps">list_scenario_gaps</code></td><td>List a project’s scenario gaps, ranked: the tests that do not exist yet, each with its class, evidence lines and exposure score.</td><td><code>projectId</code> (required), <code>class</code>, <code>feature</code>, <code>minScore</code>, <code>pr</code>, <code>limit</code></td><td><a href="/features/scenario-gaps.html"><code>test-map</code></a></td></tr><tr><td><code id="draft_scenario">draft_scenario</code></td><td>Draft a deterministic test skeleton for a scenario gap, as text to paste or hand to an agent; nothing is committed.</td><td><code>projectId</code> (required), <code>gapId</code> (required)</td><td><a href="/features/scenario-gaps.html"><code>test-map</code></a></td></tr><tr><td><code id="get_feature_graph">get_feature_graph</code></td><td>Walk the feature graph around a node: the tests, pages, controls, routes, handlers and dependencies within <code>depth</code> hops, and the edges between them.</td><td><code>projectId</code> (required), <code>node</code> (required), <code>depth</code></td><td><a href="/features/scenario-gaps.html"><code>test-map</code></a></td></tr><tr><td><code id="get_quality_report">get_quality_report</code></td><td>Get a quality report as its bundle: a built-in dashboard rendered over a scope, every string already formatted.</td><td><code>dashboard</code>, <code>lang</code>, <code>projectIds</code>, <code>period</code>, <code>compare</code>, <code>environments</code>, <code>branches</code>, <code>allBranches</code>, <code>selection</code>, <code>tags</code>, <code>owners</code></td><td><a href="/features/quality-reports.html"><code>quality-reports</code></a></td></tr><tr><td><code id="list_bug_reports">list_bug_reports</code></td><td>List a project’s bug reports from Piwi Picker, newest first.</td><td><code>projectId</code> (required), <code>status</code>, <code>pageSize</code>, <code>cursor</code></td><td><a href="/features/bug-reports.html"><code>bug-reports</code></a></td></tr><tr><td><code id="get_bug_report">get_bug_report</code></td><td>Get one bug report with its steps, what each expected assertion found instead, its evidence and the test that reproduces it.</td><td><code>id</code> (required)</td><td><a href="/features/bug-reports.html"><code>bug-reports</code></a></td></tr><tr><td><code id="render_steps">render_steps</code></td><td>Render a steps document as a Playwright spec, with the converter every Piwi surface uses.</td><td><code>bugReportId</code>, <code>mode</code>, <code>steps</code>, <code>options</code></td><td><a href="/features/bug-reports.html"><code>bug-reports</code></a></td></tr></tbody></table><h2 id="healing" tabindex="-1">Healing <a class="header-anchor" href="#healing" aria-label="Permalink to &quot;Healing&quot;">​</a></h2><p>2 of the 86 tools. Setup offers this module as <strong>Fix faster</strong>: locator healing and auto-heal pull requests.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Parameters</th><th>Capability</th></tr></thead><tbody><tr><td><code id="get_locator_healing">get_locator_healing</code></td><td>Get ranked replacements for a failing execution’s broken locator, with a ready-to-apply edit.</td><td><code>executionId</code> (required)</td><td><a href="/features/locator-healing.html"><code>locator-healing</code></a></td></tr><tr><td><code id="predict_locator_breaks">predict_locator_breaks</code></td><td>Predict which of a project’s test locators a change breaks, before any test runs.</td><td><code>projectId</code> (required), <code>diff</code> (required), <code>branch</code></td><td>none</td></tr></tbody></table><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p>6 of the 86 tools. Setup offers this module as <strong>Let agents in</strong>: AI diagnosis over your real diff, and the assistant.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it returns or does</th><th>Parameters</th><th>Capability</th></tr></thead><tbody><tr><td><code id="get_cluster_diagnosis">get_cluster_diagnosis</code></td><td>Get the stored diagnosis of a failure cluster: category, confidence, root cause, evidence and suggested fix.</td><td><code>clusterId</code> (required)</td><td>none</td></tr><tr><td><code id="get_execution_diagnosis">get_execution_diagnosis</code></td><td>Get the stored diagnosis of one failing execution, in the shape <code>get_cluster_diagnosis</code> returns.</td><td><code>executionId</code> (required)</td><td>none</td></tr><tr><td><code id="submit_diagnosis_feedback">submit_diagnosis_feedback</code></td><td>Rate a stored diagnosis thumbs up or down, with an optional note.</td><td><code>diagnosisId</code> (required), <code>feedback</code>, <code>feedbackNote</code></td><td><a href="/guide/ai-provider.html"><code>ai</code></a></td></tr><tr><td><code id="run_cluster_diagnosis">run_cluster_diagnosis</code></td><td>Run Piwi’s AI diagnosis of a failure cluster and return it: category, confidence, root cause and suggested fix.</td><td><code>clusterId</code> (required), <code>force</code>, <code>baseCommit</code></td><td><a href="/guide/ai-provider.html"><code>ai</code></a></td></tr><tr><td><code id="run_execution_diagnosis">run_execution_diagnosis</code></td><td>Run Piwi’s AI diagnosis of one failing execution and return it: category, confidence, root cause and suggested fix.</td><td><code>executionId</code> (required), <code>force</code>, <code>additionalContext</code>, <code>baseCommit</code></td><td><a href="/guide/ai-provider.html"><code>ai</code></a></td></tr><tr><td><code id="record_diagnosis">record_diagnosis</code></td><td>Record a diagnosis you wrote as the current diagnosis of a failure cluster or of one failing execution.</td><td><code>clusterId</code>, <code>executionId</code>, <code>model</code> (required), <code>diagnosis</code> (required)</td><td><a href="/features/ai-diagnosis.html"><code>agent-diagnoses</code></a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/mcp.html">MCP server</a>: authentication, client setup and prompts</li><li><a href="/features/agent-skills.html">Agent skills</a>: the workflows that call these tools</li><li><a href="/operate/capabilities.html">Choose what you use</a>: declining a capability or a module</li></ul>',17)])])}const g=t(c,[["render",s]]);export{p as __pageData,g as default};
